/**
 * showcase-web — web mockup that can render as a browser window OR tablet.
 *
 * `frame: "browser"` shows traffic-light dots + address bar.
 * `frame: "tablet"` shows a clean rounded frame.
 * Same 3D tilt entrance + slide-up animation pattern as showcase-phone.
 * Blue placeholder with dimensions when no screenshot uploaded.
 */

import React from "react";
import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import { resolveTokens } from "./tokens";
import { TemplateText } from "./template-text";
import type { TextArchetype } from "./text-archetypes";
import { interpolate, spring, SPRING_SMOOTH, type SpringConfig } from "../react-animations/animation-utils";
import { gradientBackground } from "./color-utils";
import { WebScreenFill } from "../primitives/devices/DesignedScreenFill";

const SPRING_WEB: SpringConfig = { damping: 20, stiffness: 100 };

export const showcaseWebSchema: Record<string, VariableField> = {
  frame: {
    type: "enum",
    label: "Device frame",
    default: "browser",
    options: ["browser", "tablet"],
    description: "browser shows chrome bar + address bar, tablet shows clean frame",
  },
  texts: {
    type: "string",
    label: "Text",
    default: "See it in action.",
    required: true,
    description: "Title text shown on the scene",
  },
  screenMediaUrl: {
    type: "media",
    label: "Screenshot",
    description: "Screenshot to show in the device window",
  },
  screen1Url: {
    type: "media",
    label: "Screen 1",
  },
  screen2Url: {
    type: "media",
    label: "Screen 2",
  },
  addressBarUrl: {
    type: "string",
    label: "Address bar URL",
    default: "yourapp.com",
    description: "URL shown in browser chrome (browser frame only)",
  },
  textColor: {
    type: "color",
    label: "Text color",
    default: "",
    description: "Override text color (leave empty for auto)",
  },
};

export const showcaseWebDefaults: Record<string, unknown> = {
  frame: "browser",
  texts: "See it in action.",
  screenMediaUrl: "",
  screen1Url: "",
  screen2Url: "",
  addressBarUrl: "yourapp.com",
  textColor: "",
};

export const ShowcaseWebTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  beatIntensity,
  width,
  height,
  textArchetype,
  safeZone,
  sceneDuration,
}) => {
  const s = Math.min(width, height) / 1080;
  const { accent, secondary, content, font } = resolveTokens(style);
  const textColor = String(variables.textColor || "") || content;
  const textsRaw = String(variables.texts || "");
  const gradSeed = textsRaw.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0);
  const frameType = String(variables.frame || "browser").toLowerCase() === "tablet" ? "tablet" : "browser";
  const isBrowser = frameType === "browser";
  const screenMediaUrl = String(variables.screenMediaUrl || "");
  const addressBarUrl = String(variables.addressBarUrl || "yourapp.com");
  // No useState for imgError — templates must be stateless (re-rendered per frame)

  // ── Slides mode detection — include main screenshot + extra screens ──
  const extraScreens = [
    String(variables.screen1Url || ""),
    String(variables.screen2Url || ""),
  ].filter(Boolean);
  // When extra screens exist, use main screenshot as first slide
  const slidesMode = extraScreens.length > 0;
  const screens = slidesMode && screenMediaUrl
    ? [screenMediaUrl, ...extraScreens]
    : extraScreens;

  // ── Device dimensions — fit in both orientations ──────────────
  const deviceWidth = Math.min(width * 0.85, height * 0.55 * (16 / 9));
  const chromeHeight = isBrowser ? 44 * s : 0;
  const contentHeight = deviceWidth * (9 / 16);
  const deviceHeight = chromeHeight + contentHeight;
  const borderRadius = isBrowser ? 12 * s : 24 * s;
  const borderWidth = isBrowser ? 0 : 6 * s;

  // ── 3D perspective tilt entrance ────────────────────────────────
  // Device starts lying flat (rotateX 70°) and lifts up to face viewer
  const enterRange: [number, number] = slidesMode ? [0.02, 0.35] : [0.02, 0.85];
  const enterP = spring(
    interpolate(progress, enterRange, [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
    { damping: 28, stiffness: 80 },
  );
  const rotateX = (1 - enterP) * 70; // 70° → 0°
  const deviceY = (1 - enterP) * 150 * s; // slight lift
  const deviceScale = interpolate(enterP, [0, 1], [0.85, 1]);
  const deviceOpacity = interpolate(progress, [0.02, 0.1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // ── Screen slide offsets (slides mode only) — each screen gets equal time ──
  const slideCount = screens.length;
  let slideOffset = 0;
  if (slidesMode && slideCount >= 2) {
    // Each screen gets an equal slice of progress. Transition happens at the boundary.
    // For 2 screens: slide at 0.5. For 3 screens: slide at 0.33 and 0.66.
    const transitionWidth = 0.1;

    let totalSlides = 0;
    for (let i = 1; i < slideCount; i++) {
      const boundary = i / slideCount;
      const start = boundary - transitionWidth / 2;
      const end = boundary + transitionWidth / 2;
      totalSlides += spring(
        interpolate(progress, [start, end], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
        SPRING_SMOOTH,
      );
    }
    slideOffset = -totalSlides * deviceWidth;
  }

  const beatScale = slidesMode ? 1 + beatIntensity * 0.01 : 1 + beatIntensity * 0.015;

  // ── Traffic light dot sizes ───────────────────────────────────
  const dotSize = 12 * s;
  const dotGap = 8 * s;

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: "#000",
        position: "relative",
        overflow: "hidden",
        fontFamily: font,
      }}
    >
      {/* Gradient background */}
      <div style={{ position: "absolute", inset: 0, background: gradientBackground({ colorA: accent, colorB: secondary, solidBg: style.brandKit?.bg, progress, sceneDuration, seed: gradSeed, family: resolveTokens(style).preset.background }), pointerEvents: "none" }} />

      {/* Text overlay — anchored to TOP so it sits above the browser frame
          rather than overlapping it. */}
      <TemplateText
        typeTreatment={resolveTokens(style).preset.type}
        archetype={(textArchetype as TextArchetype) ?? "subtle"}
        text={String(variables.texts ?? "")}
        progress={progress}
        sceneDuration={sceneDuration ?? 3}
        width={width}
        height={height}
        position="top"
        sizeRole="headline"
        safeZone={safeZone}
        font={font}
        color={textColor}
        beatIntensity={beatIntensity}
      />

      {/* Device — 3D perspective tilt entrance */}
      <div
        style={{
          position: "absolute",
          top: height * 0.35,
          left: (width - deviceWidth) / 2,
          width: deviceWidth,
          height: deviceHeight,
          perspective: `${1200 * s}px`,
        }}
      >
        <div
          style={{
            width: deviceWidth,
            height: deviceHeight,
            transform: `rotateX(${rotateX}deg) translateY(${deviceY}px) scale(${deviceScale * beatScale})`,
            transformOrigin: "center bottom",
            opacity: deviceOpacity,
          }}
        >
        {/* Browser frame */}
        <div
          style={{
            width: deviceWidth,
            height: deviceHeight,
            borderRadius,
            overflow: "hidden",
            position: "relative",
            boxShadow: `0 ${20 * s}px ${60 * s}px rgba(0,0,0,0.35)`,
          }}
        >
          {/* Chrome bar — browser frame only */}
          {isBrowser && (
            <div
              style={{
                width: "100%",
                height: 44 * s,
                backgroundColor: "#e8e8e8",
                display: "flex",
                alignItems: "center",
                paddingLeft: 16 * s,
                paddingRight: 16 * s,
                gap: 0,
                position: "relative",
                zIndex: 2,
              }}
            >
              {/* Traffic light dots */}
              <div style={{ display: "flex", gap: dotGap, flexShrink: 0 }}>
                <div style={{ width: dotSize, height: dotSize, borderRadius: "50%", backgroundColor: "#ff5f57" }} />
                <div style={{ width: dotSize, height: dotSize, borderRadius: "50%", backgroundColor: "#febc2e" }} />
                <div style={{ width: dotSize, height: dotSize, borderRadius: "50%", backgroundColor: "#28c840" }} />
              </div>

              {/* Address bar */}
              <div
                style={{
                  flex: 1,
                  marginLeft: 16 * s,
                  height: 28 * s,
                  backgroundColor: "#ffffff",
                  borderRadius: 6 * s,
                  display: "flex",
                  alignItems: "center",
                  paddingLeft: 12 * s,
                  paddingRight: 12 * s,
                  overflow: "hidden",
                }}
              >
                {/* Lock icon */}
                <svg
                  width={14 * s}
                  height={14 * s}
                  viewBox="0 0 14 14"
                  fill="none"
                  style={{ flexShrink: 0, marginRight: 6 * s }}
                >
                  <rect x="2" y="6" width="10" height="7" rx="1.5" fill="#999" />
                  <path d="M4.5 6V4.5a2.5 2.5 0 015 0V6" stroke="#999" strokeWidth="1.5" fill="none" strokeLinecap="round" />
                </svg>
                <span
                  style={{
                    fontSize: 13 * s,
                    fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
                    color: "#666",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {addressBarUrl}
                </span>
              </div>
            </div>
          )}

          {/* Tablet border frame overlay — tablet frame only */}
          {!isBrowser && (
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius,
                border: `${borderWidth * 1.5}px solid rgba(220,220,220,0.6)`,
                pointerEvents: "none",
                zIndex: 2,
              }}
            />
          )}

          {/* Screen content */}
          {slidesMode ? (
            /* Sliding screen strip — 3 screens side by side */
            <div
              style={{
                position: "absolute",
                top: chromeHeight,
                left: 0,
                width: deviceWidth * screens.length,
                height: contentHeight,
                display: "flex",
                transform: `translateX(${slideOffset}px)`,
              }}
            >
              {screens.map((url, i) => (
                <div
                  key={i}
                  style={{
                    width: deviceWidth,
                    height: contentHeight,
                    flexShrink: 0,
                  }}
                >
                  {url ? (
                    <img src={url} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                  ) : (
                    <WebScreenFill
                      accent={accent}
                      secondary={secondary}
                      bg={style.brandKit?.bg}
                      font={font}
                      s={s}
                      w={deviceWidth}
                      h={contentHeight}
                      progress={progress}
                    />
                  )}
                </div>
              ))}
            </div>
          ) : screenMediaUrl ? (
            <img
              src={screenMediaUrl}
              style={{ width: "100%", height: contentHeight, objectFit: "cover", display: "block" }}
            />
          ) : (
            <div style={{ width: "100%", height: contentHeight }}>
              <WebScreenFill
                accent={accent}
                secondary={secondary}
                bg={style.brandKit?.bg}
                font={font}
                s={s}
                w={deviceWidth}
                h={contentHeight}
                progress={progress}
              />
            </div>
          )}
        </div>
        </div>
      </div>
    </div>
  );
};

/**
 * DesignedScreenFill — brand-tinted "designed product UI" used to fill a device
 * screen when no real screenshot is supplied.
 *
 * Two variants:
 *  - WebScreenFill   → SaaS-dashboard look (header bar + sidebar + stat cards + chart)
 *  - PhoneScreenFill → mobile-app look (status bar + header + list cards + tab bar)
 *
 * Render constraints (template rules): inline styles only, NO external images,
 * NO CSS `filter`, deterministic from `progress` (no rAF / transitions). Must
 * render identically across preview / client-SVG export / server Puppeteer.
 */

import { interpolate } from "../../react-animations/animation-utils";

// ─── Local color helpers (self-contained — no hex deps) ─────────────────────
function parseHex(hex: string): [number, number, number] | null {
  const m = String(hex).match(/^#([0-9a-f]{3,8})$/i);
  if (!m) return null;
  const h = m[1];
  if (h.length === 3) {
    return [parseInt(h[0] + h[0], 16), parseInt(h[1] + h[1], 16), parseInt(h[2] + h[2], 16)];
  }
  if (h.length >= 6) {
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }
  return null;
}

function rgba(hex: string, a: number): string {
  const p = parseHex(hex);
  if (!p) return hex;
  return `rgba(${p[0]},${p[1]},${p[2]},${a})`;
}

function isDark(hex: string): boolean {
  const p = parseHex(hex);
  if (!p) return false;
  const [r, g, b] = p;
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255 < 0.5;
}

export interface ScreenFillProps {
  /** Brand accent (primary). */
  accent: string;
  /** Brand secondary (second chart series / chips). */
  secondary: string;
  /** Brand background — decides whether the surface reads light or dark. */
  bg?: string;
  font: string;
  /** Per-template scale factor (Math.min(w,h)/1080). */
  s: number;
  /** Width of the screen area in px. */
  w: number;
  /** Height of the screen area in px. */
  h: number;
  /** Scene progress 0→1 (drives a calm chart/progress grow). */
  progress: number;
}

// Surface palette derived from whether the brand bg reads dark.
function surface(bg: string | undefined) {
  const dark = bg ? isDark(bg) : false;
  return dark
    ? {
        dark,
        page: "#15171c",
        panel: "#1e2128",
        line: "rgba(255,255,255,0.07)",
        block: "rgba(255,255,255,0.10)",
        blockSoft: "rgba(255,255,255,0.055)",
      }
    : {
        dark,
        page: "#f5f6f8",
        panel: "#ffffff",
        line: "rgba(15,20,30,0.07)",
        block: "rgba(15,20,30,0.10)",
        blockSoft: "rgba(15,20,30,0.05)",
      };
}

const stroke = (s: number, c: string) => `${Math.max(1, Math.round(1 * s))}px solid ${c}`;

// ─── Web dashboard fill ─────────────────────────────────────────────────────
export const WebScreenFill: React.FC<ScreenFillProps> = ({ accent, secondary, bg, font, s, w, h, progress }) => {
  const c = surface(bg);
  const pad = Math.round(h * 0.055);
  const headerH = Math.round(h * 0.13);
  const sidebarW = Math.round(w * 0.18);
  const grow = interpolate(progress, [0.1, 0.7], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Fixed bar heights (no Math.random — deterministic).
  const bars = [0.55, 0.78, 0.4, 0.92, 0.66, 0.84, 0.5];
  const chartH = h - headerH - pad * 2 - Math.round(h * 0.22) - Math.round(h * 0.04);

  const card = (i: number) => {
    const tint = [accent, secondary, accent][i % 3];
    return (
      <div
        key={i}
        style={{
          flex: 1,
          height: Math.round(h * 0.22),
          backgroundColor: c.panel,
          borderRadius: Math.round(12 * s),
          border: stroke(s, c.line),
          padding: Math.round(h * 0.03),
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          boxSizing: "border-box",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: Math.round(8 * s) }}>
          <div style={{ width: Math.round(h * 0.05), height: Math.round(h * 0.05), borderRadius: Math.round(7 * s), backgroundColor: rgba(tint, c.dark ? 0.28 : 0.16) }} />
          <div style={{ width: "42%", height: Math.round(h * 0.018), borderRadius: 99, backgroundColor: c.blockSoft }} />
        </div>
        <div style={{ width: "62%", height: Math.round(h * 0.05), borderRadius: Math.round(5 * s), backgroundColor: c.block }} />
        <div style={{ width: "34%", height: Math.round(h * 0.016), borderRadius: 99, backgroundColor: rgba(tint, c.dark ? 0.7 : 0.55) }} />
      </div>
    );
  };

  return (
    <div style={{ width: "100%", height: "100%", backgroundColor: c.page, fontFamily: font, display: "flex", flexDirection: "column", boxSizing: "border-box", overflow: "hidden" }}>
      {/* Top header bar — brand accent */}
      <div
        style={{
          height: headerH,
          backgroundColor: accent,
          display: "flex",
          alignItems: "center",
          paddingLeft: pad,
          paddingRight: pad,
          gap: Math.round(10 * s),
          flexShrink: 0,
        }}
      >
        <div style={{ width: Math.round(h * 0.05), height: Math.round(h * 0.05), borderRadius: Math.round(8 * s), backgroundColor: "rgba(255,255,255,0.92)" }} />
        <div style={{ width: Math.round(w * 0.18), height: Math.round(h * 0.022), borderRadius: 99, backgroundColor: "rgba(255,255,255,0.85)" }} />
        <div style={{ flex: 1 }} />
        <div style={{ width: Math.round(w * 0.1), height: Math.round(h * 0.04), borderRadius: 99, backgroundColor: "rgba(255,255,255,0.22)" }} />
        <div style={{ width: Math.round(h * 0.06), height: Math.round(h * 0.06), borderRadius: "50%", backgroundColor: "rgba(255,255,255,0.85)" }} />
      </div>

      <div style={{ flex: 1, display: "flex", minHeight: 0 }}>
        {/* Sidebar */}
        <div style={{ width: sidebarW, backgroundColor: c.panel, borderRight: stroke(s, c.line), padding: pad, display: "flex", flexDirection: "column", gap: Math.round(h * 0.028), boxSizing: "border-box", flexShrink: 0 }}>
          {[0, 1, 2, 3, 4].map((i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: Math.round(8 * s) }}>
              <div style={{ width: Math.round(h * 0.032), height: Math.round(h * 0.032), borderRadius: Math.round(5 * s), backgroundColor: i === 0 ? accent : c.block }} />
              <div style={{ flex: 1, height: Math.round(h * 0.016), borderRadius: 99, backgroundColor: i === 0 ? rgba(accent, 0.55) : c.blockSoft }} />
            </div>
          ))}
        </div>

        {/* Content */}
        <div style={{ flex: 1, padding: pad, display: "flex", flexDirection: "column", gap: pad, minWidth: 0, boxSizing: "border-box" }}>
          <div style={{ display: "flex", gap: pad }}>{[0, 1, 2].map(card)}</div>

          {/* Chart panel */}
          <div style={{ flex: 1, backgroundColor: c.panel, borderRadius: Math.round(12 * s), border: stroke(s, c.line), padding: Math.round(h * 0.03), display: "flex", flexDirection: "column", boxSizing: "border-box", minHeight: 0 }}>
            <div style={{ width: "30%", height: Math.round(h * 0.02), borderRadius: 99, backgroundColor: c.block, marginBottom: Math.round(h * 0.03) }} />
            <div style={{ flex: 1, display: "flex", alignItems: "flex-end", gap: Math.round(w * 0.018), minHeight: 0 }}>
              {bars.map((bh, i) => (
                <div key={i} style={{ flex: 1, height: Math.max(2, Math.round(chartH * bh * grow)), borderRadius: Math.round(4 * s), backgroundColor: i % 2 === 0 ? accent : rgba(secondary, c.dark ? 0.85 : 0.7) }} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// ─── Phone app fill ──────────────────────────────────────────────────────────
export const PhoneScreenFill: React.FC<ScreenFillProps> = ({ accent, secondary, bg, font, s, w, h, progress }) => {
  const c = surface(bg);
  const pad = Math.round(w * 0.07);
  const statusH = Math.round(h * 0.04);
  const headerH = Math.round(h * 0.14);
  const grow = interpolate(progress, [0.12, 0.7], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const onAccent = "rgba(255,255,255,";

  const listItem = (i: number) => {
    const tint = [accent, secondary][i % 2];
    return (
      <div
        key={i}
        style={{
          backgroundColor: c.panel,
          borderRadius: Math.round(16 * s),
          border: stroke(s, c.line),
          padding: Math.round(w * 0.05),
          display: "flex",
          alignItems: "center",
          gap: Math.round(w * 0.045),
          boxSizing: "border-box",
        }}
      >
        <div style={{ width: Math.round(w * 0.13), height: Math.round(w * 0.13), borderRadius: Math.round(12 * s), backgroundColor: rgba(tint, c.dark ? 0.3 : 0.18), flexShrink: 0 }} />
        <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: Math.round(h * 0.012) }}>
          <div style={{ width: `${70 - i * 8}%`, height: Math.round(h * 0.018), borderRadius: 99, backgroundColor: c.block }} />
          <div style={{ width: `${48 - i * 4}%`, height: Math.round(h * 0.014), borderRadius: 99, backgroundColor: c.blockSoft }} />
        </div>
        <div style={{ width: Math.round(w * 0.12), height: Math.round(h * 0.026), borderRadius: 99, backgroundColor: rgba(tint, c.dark ? 0.6 : 0.5) }} />
      </div>
    );
  };

  return (
    <div style={{ width: "100%", height: "100%", backgroundColor: c.page, fontFamily: font, display: "flex", flexDirection: "column", boxSizing: "border-box", overflow: "hidden" }}>
      {/* Status bar */}
      <div style={{ height: statusH, display: "flex", alignItems: "center", justifyContent: "space-between", paddingLeft: pad, paddingRight: pad, flexShrink: 0 }}>
        <div style={{ width: Math.round(w * 0.1), height: Math.round(h * 0.012), borderRadius: 99, backgroundColor: c.block }} />
        <div style={{ display: "flex", gap: Math.round(4 * s) }}>
          <div style={{ width: Math.round(w * 0.04), height: Math.round(h * 0.012), borderRadius: 2, backgroundColor: c.block }} />
          <div style={{ width: Math.round(w * 0.03), height: Math.round(h * 0.012), borderRadius: 2, backgroundColor: c.block }} />
        </div>
      </div>

      {/* Header — brand accent */}
      <div style={{ height: headerH, backgroundColor: accent, padding: pad, display: "flex", flexDirection: "column", justifyContent: "center", gap: Math.round(h * 0.018), flexShrink: 0 }}>
        <div style={{ width: "44%", height: Math.round(h * 0.02), borderRadius: 99, backgroundColor: `${onAccent}0.5)` }} />
        <div style={{ width: "70%", height: Math.round(h * 0.032), borderRadius: Math.round(5 * s), backgroundColor: `${onAccent}0.92)` }} />
      </div>

      {/* Highlight / progress card */}
      <div style={{ padding: pad, paddingBottom: 0 }}>
        <div style={{ backgroundColor: c.panel, borderRadius: Math.round(16 * s), border: stroke(s, c.line), padding: Math.round(w * 0.05), display: "flex", flexDirection: "column", gap: Math.round(h * 0.018), boxSizing: "border-box" }}>
          <div style={{ width: "50%", height: Math.round(h * 0.016), borderRadius: 99, backgroundColor: c.blockSoft }} />
          <div style={{ width: "100%", height: Math.round(h * 0.012), borderRadius: 99, backgroundColor: c.blockSoft, position: "relative", overflow: "hidden" }}>
            <div style={{ position: "absolute", inset: 0, width: `${Math.round(grow * 72)}%`, borderRadius: 99, backgroundColor: accent }} />
          </div>
        </div>
      </div>

      {/* List items */}
      <div style={{ flex: 1, padding: pad, display: "flex", flexDirection: "column", gap: Math.round(h * 0.018), minHeight: 0 }}>
        {[0, 1, 2, 3].map(listItem)}
      </div>

      {/* Bottom tab bar */}
      <div style={{ height: Math.round(h * 0.075), backgroundColor: c.panel, borderTop: stroke(s, c.line), display: "flex", alignItems: "center", justifyContent: "space-around", flexShrink: 0 }}>
        {[0, 1, 2, 3].map((i) => (
          <div key={i} style={{ width: Math.round(w * 0.06), height: Math.round(w * 0.06), borderRadius: Math.round(7 * s), backgroundColor: i === 0 ? accent : c.block }} />
        ))}
      </div>
    </div>
  );
};

/**
 * TemplateText — unified text component for scene templates.
 *
 * Replaces the per-template hand-rolled text rendering with a single component
 * that owns: archetype motion lifecycle (entrance + hold + exit), font sizing,
 * position, beat pulse, and safe zone.
 *
 * Each template declares its constraints (position + sizeRole) at the call site;
 * the user/AI picks the archetype. Templates that can only show text at the top
 * just always pass position="top".
 *
 * Example — a data template (caption above a chart):
 *
 *   <TemplateText
 *     archetype={textArchetype}
 *     text={variables.title}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     position="top"
 *     sizeRole="caption"
 *   />
 *
 * Example — a media template (full-frame headline):
 *
 *   <TemplateText
 *     archetype={textArchetype}
 *     text={variables.headline}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     position="center"
 *     sizeRole="headline"
 *     beatIntensity={beatIntensity}
 *   />
 *
 * Note: `textArchetype` is destructured from props (a scene-level
 * field on `SceneTemplateProps`), NOT read from `variables`. Copying
 * the wrong pattern silently no-ops — the executor routes
 * `setSceneVariable("textArchetype", ...)` to the scene-level field,
 * never into variables, so `variables.textArchetype` is always
 * undefined.
 */

import {
  renderArchetype,
  normalizeArchetype,
  type TextArchetype,
  type ArchetypeRender,
} from "./text-archetypes";
import type { TypeTreatment } from "./tokens";
import { renderWithEmoji, planTypewriterEmoji } from "../emoji/emoji-text";
import { Emoji } from "../emoji";

export type TextPosition = "top" | "center" | "bottom";
export type TextSizeRole = "headline" | "caption" | "label";

export interface SafeZone {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface TemplateTextProps {
  archetype: TextArchetype;
  text: string;
  /** Scene progress 0→1. */
  progress: number;
  /** Scene duration in seconds — drives entrance/exit phase scaling. */
  sceneDuration: number;
  /** Frame width in pixels (1080 in production, smaller in previews). */
  width: number;
  /** Frame height in pixels (1920 in production). */
  height: number;
  /** Where the text box sits in the frame. Templates declare this. */
  position?: TextPosition;
  /** Size envelope. Templates declare this. */
  sizeRole?: TextSizeRole;
  /** Preset type treatment — weight/tracking/size/case shift from style.preset. */
  typeTreatment?: TypeTreatment;
  /** Padding from frame edges. Defaults to a 24px box. */
  safeZone?: SafeZone;
  /** Font family. */
  font?: string;
  /** Fill color. */
  color?: string;
  /** Beat intensity 0→1 (currently unused — kept for forward compat). */
  beatIntensity?: number;
}

const DEFAULT_SAFE_ZONE: SafeZone = { top: 24, right: 24, bottom: 24, left: 24 };
const DEFAULT_FONT =
  "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";

// ─── Typography constants ───────────────────────────────────────
// All em-based so they scale with font size and behave consistently across
// font families. Values from print/motion-design conventions:
//
//  - Big text (display/headline) gets TIGHTER tracking and TIGHTER leading.
//    -0.022em (≈ -2.2%) is the sweet spot for 48–88px headlines on most
//    sans-serifs (Inter, Helvetica, SF Pro, Manrope, Geist).
//  - Word-spacing kept subtle (≤0.08em). CSS word-spacing is ADDITIVE on
//    top of the natural space char, so what looks like "a touch of
//    rhythm" in print becomes a visible double-gap on 80px motion
//    headlines (especially under wordStagger, where each word renders
//    as an inline-block and the gap between them is preserved). Old
//    values (0.16/0.18/0.22 em) added ~13–18px per gap on display
//    type — the "too much space between words" symptom.
//  - Line-height 1.1 for headlines, 1.5 for body — Bringhurst-aligned ratios.
//  - kern + liga always on so any font's pair-kerning and ligatures fire
//    consistently (works across Inter, Manrope, SF, IBM Plex, etc.).
const TYPO = {
  headline: {
    letterSpacing: "-0.022em",
    wordSpacing: "0.04em",
    lineHeight: 1.1,
  },
  caption: {
    letterSpacing: "-0.012em",
    wordSpacing: "0.06em",
    lineHeight: 1.25,
  },
  label: {
    letterSpacing: "-0.005em",
    wordSpacing: "0.10em",
    lineHeight: 1.4,
  },
};
const FONT_FEATURES = '"kern" 1, "liga" 1';

// Drop shadow tuned to give crisp edges on retina without muddying text on
// saturated gradients. Earlier two-layer shadow (1px tight + 16px wide) cast
// dark halos that made gradient-backed text look smudged. A single barely-
// there shadow is enough for edge definition; bg-media adds its own dark
// scrim for legibility over photos, so we don't need to compensate here.
function dropShadowFor(textColor: string): string {
  const dark = isLikelyDark(textColor);
  const tone = dark ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.2)";
  return `0 1px 2px ${tone}`;
}

function isLikelyDark(color: string): boolean {
  // Crude luminance check — handles #rrggbb and #rgb. Anything we can't parse
  // (named colors, rgb()) defaults to "not dark" so the heavier shadow shows.
  const m = color.replace("#", "");
  if (m.length === 3) {
    const r = parseInt(m[0] + m[0], 16);
    const g = parseInt(m[1] + m[1], 16);
    const b = parseInt(m[2] + m[2], 16);
    return (r * 299 + g * 587 + b * 114) / 1000 < 128;
  }
  if (m.length === 6) {
    const r = parseInt(m.slice(0, 2), 16);
    const g = parseInt(m.slice(2, 4), 16);
    const b = parseInt(m.slice(4, 6), 16);
    return (r * 299 + g * 587 + b * 114) / 1000 < 128;
  }
  return false;
}
// ─── Font sizing matrix ─────────────────────────────────────────
// Mirrors what production templates actually render today, ported from:
//   - text-overlay.tsx (headline: 80/64/48 × s_min by char count)
//   - infographic-steps.tsx (caption: ~44 × s_min capped by layout)

/**
 * Compute heroWord font size for a single word. Each active word fills its
 * own moment — trailer convention. Center can go large (480ref cap); top
 * stays inside the top zone height so it doesn't crash into the animation
 * or data viz below.
 */
function computeHeroFontSize(
  wordChars: number,
  position: TextPosition,
  width: number,
  height: number,
  safeZone: SafeZone,
): number {
  const chars = Math.max(wordChars, 1);
  const s_min = Math.min(width, height) / 1080;
  const widthBudget = (width - safeZone.left - safeZone.right) * 0.92;
  const pxPerChar = 0.58; // bold sans-serif approximation
  const widthCap = widthBudget / (chars * pxPerChar);

  if (position === "center") {
    return Math.min(480 * s_min, widthCap);
  }

  // Top/bottom: keep the word inside its zone (~28% of frame height) with
  // 80% headroom for entrance overshoot + breathe. Reference target 220ref
  // so even short words stay big without overflowing the zone.
  const heightCap = height * 0.28 * 0.8;
  return Math.min(220 * s_min, widthCap, heightCap);
}

/**
 * Smooth interpolation between max and min font size based on character count.
 * Avoids the visible "jump" you get from bucket boundaries when copy length
 * crosses a threshold (e.g., 25→26 chars dropping headline from 80px to 64px).
 *
 * Exported so templates that lay out their own text can match the headline
 * curve instead of inventing their own bucketed scaling.
 *
 * Returns size at 1080-reference scale; caller multiplies by s_min.
 */
export function smoothSize(chars: number, maxChars: number, max: number, min: number): number {
  const t = Math.max(0, Math.min(1, chars / maxChars));
  // Slight curve so short text stays at maxSize longer before scaling down.
  const eased = t * t;
  return max - (max - min) * eased;
}

function computeFontSize(
  archetype: TextArchetype,
  text: string,
  role: TextSizeRole,
  position: TextPosition,
  width: number,
  height: number,
  safeZone: SafeZone,
): { fontSize: number; fontWeight: number } {
  const s_min = Math.min(width, height) / 1080;

  // heroWord container fontSize uses the longest word as a safe fallback. The
  // ACTIVE-word size is recomputed per-render in the "hero" render branch
  // (via computeHeroFontSize) so each word fills its own moment optimally —
  // trailer convention.
  if (archetype === "heroWord") {
    const longestChars = text
      .split(/\s+/)
      .filter(Boolean)
      .reduce((m, w) => Math.max(m, w.length), 1);
    return {
      fontSize: computeHeroFontSize(longestChars, position, width, height, safeZone),
      fontWeight: 800,
    };
  }

  const chars = text.length;

  // Smooth scaling, minimums set so even long copy stays readable in production
  // (1080 reference). Numbers tuned to match — but improve on — the previous
  // bucketed system.
  if (role === "headline") {
    // Floor 60 (was 48) — matches the typography guideline "Titles/headlines
    // 60-86px at 1080" and lifts long-copy headlines off the body-text floor
    // that left ProblemSolution-shaped statements feeling small. Max held at
    // 88 so short, punchy headlines still fill the frame.
    const refSize = smoothSize(chars, /* maxChars */ 70, /* max */ 88, /* min */ 60);
    return { fontSize: refSize * s_min, fontWeight: 700 };
  }

  if (role === "caption") {
    const refSize = smoothSize(chars, 80, 48, 32);
    return { fontSize: refSize * s_min, fontWeight: 600 };
  }

  // label
  const refSize = smoothSize(chars, 80, 34, 24);
  return { fontSize: refSize * s_min, fontWeight: 500 };
}

// ─── Positioning ───────────────────────────────────────────────

function positionStyle(
  position: TextPosition,
  height: number,
  safeZone: SafeZone,
): React.CSSProperties {
  switch (position) {
    case "top":
      return {
        top: safeZone.top + height * 0.06,
        height: height * 0.28,
        alignItems: "flex-start",
      };
    case "bottom":
      return {
        bottom: safeZone.bottom + height * 0.06,
        height: height * 0.28,
        alignItems: "flex-end",
      };
    case "center":
    default:
      return {
        top: 0,
        bottom: 0,
        alignItems: "center",
      };
  }
}

// ─── Component ─────────────────────────────────────────────────

export const TemplateText: React.FC<TemplateTextProps> = ({
  archetype: archetypeRaw,
  text: textRaw,
  progress,
  sceneDuration,
  width,
  height,
  position = "center",
  sizeRole = "headline",
  typeTreatment,
  safeZone = DEFAULT_SAFE_ZONE,
  font = DEFAULT_FONT,
  color = "#FFFFFF",
  beatIntensity = 0,
}) => {
  // Defensive coerce: TemplateText is downstream of ~16 templates that pass
  // their own `variables.X` strings. If any one of them passes undefined
  // (missing variable on a freshly added scene, stale saved config, vibecoded
  // template not setting a field), the unguarded `.split` / `.length` calls
  // below crash the entire Studio preview. Treat undefined/non-string as
  // empty so a single bad scene doesn't take everything down. Warn in dev
  // so the upstream gap still surfaces.
  const textSafe = typeof textRaw === "string" ? textRaw : "";
  if (textRaw !== undefined && typeof textRaw !== "string" && import.meta.env.DEV) {
    console.warn("[TemplateText] received non-string text:", textRaw);
  }
  // `|` is the AI's explicit line-break convention for headline copy
  // ("Built for speed.|Designed for you."). Convert centrally so EVERY
  // template that renders text through TemplateText honors it — bg-media
  // used to convert locally while confetti/emojiBurst/etc. rendered the
  // pipe literally. Whitespace around the pipe is trimmed so spaced and
  // unspaced pipes produce identical output. The container's
  // `white-space: pre-line` renders the resulting `\n` as a hard break.
  // Templates that legitimately render pipes (code, terminal commands)
  // don't flow through TemplateText, so they're unaffected.
  const text = textSafe.replace(/\s*\|\s*/g, "\n");
  // Normalize the archetype prop so legacy effect names from old saved
  // configs (e.g., "fade-in") map to a real archetype instead of crashing.
  const archetype = normalizeArchetype(archetypeRaw);
  const scale = Math.min(width, height) / 1080;
  // Motion pacing applies at every size role — a calm video should ease its
  // captions in too, not just its headlines. (The rest of the treatment is
  // headline-only; see `tt` below.)
  const result: ArchetypeRender = renderArchetype(
    archetype,
    progress,
    scale,
    text,
    sceneDuration,
    typeTreatment?.phaseScale ?? 1,
  );
  const { fontSize, fontWeight } = computeFontSize(
    archetype,
    text,
    sizeRole,
    position,
    width,
    height,
    safeZone,
  );

  // beatIntensity reserved for future use; currently a no-op on text body.
  void beatIntensity;

  const baseTypo = TYPO[sizeRole];
  // Preset type treatment. Absent (or the default preset's zero-deltas) leaves
  // every value exactly as it was, so unpresetted configs are unaffected.
  const tt = sizeRole === "headline" ? typeTreatment : undefined;
  // Only rewrite a value the preset actually changes — reformatting
  // letterSpacing with a zero delta would alter the emitted string (and every
  // stability snapshot) without changing the render.
  const typo = tt
    ? {
        ...baseTypo,
        ...(tt.trackingDeltaEm !== 0
          ? {
              letterSpacing: `${Number(
                (parseFloat(baseTypo.letterSpacing) + tt.trackingDeltaEm).toFixed(4),
              )}em`,
            }
          : {}),
        ...(tt.transform ? { textTransform: tt.transform } : {}),
      }
    : baseTypo;
  const presetWeight = tt ? Math.min(900, Math.max(100, fontWeight + tt.weightDelta)) : fontWeight;
  const presetSize = tt ? fontSize * tt.sizeScale : fontSize;
  const textShadow = dropShadowFor(color);

  const containerStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    right: 0,
    display: "flex",
    justifyContent: "center",
    padding: `0 ${safeZone.right}px 0 ${safeZone.left}px`,
    color,
    fontFamily: font,
    fontWeight: presetWeight,
    fontSize: presetSize,
    textAlign: "center",
    pointerEvents: "none",
    fontFeatureSettings: FONT_FEATURES,
    textRendering: "optimizeLegibility",
    WebkitFontSmoothing: "antialiased",
    MozOsxFontSmoothing: "grayscale",
    // Respect explicit newlines — the centralized `|` → `\n` conversion
    // above (and callers passing real newlines) rely on this. Multiple
    // spaces still collapse normally; only `\n` and CRLF break.
    whiteSpace: "pre-line",
    ...(textShadow ? { textShadow } : {}),
    ...typo,
    ...positionStyle(position, height, safeZone),
  };

  if (result.kind === "block") {
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.block.opacity,
            transform: `${result.block.transform}`,
            // Inherit letter-spacing from the container's typography defaults
            // unless the archetype explicitly overrides (e.g., for animated tracking).
            ...(result.block.letterSpacing ? { letterSpacing: result.block.letterSpacing } : {}),
            ...(result.block.willChange ? { willChange: result.block.willChange } : {}),
            maxWidth: "85%",
          }}
        >
          {renderWithEmoji(result.text, fontSize)}
        </div>
      </div>
    );
  }

  if (result.kind === "typewriter") {
    // Render every character as its own span so the FULL TEXT always sets the
    // layout — wrapping is decided by the complete string, not the typed
    // prefix. The cursor is overlaid with position:absolute from the last
    // typed char so it doesn't break the word it's inside.
    const chars = text.split("");
    // Map cluster-start code-unit indices → mapped emoji-PNG image so color
    // emoji render as images even in the per-char typewriter reveal. Indexing
    // stays on text.length (UTF-16 units) so result.visibleChars / charExits
    // line up exactly; continuation units of a cluster render nothing.
    const emojiPlan = planTypewriterEmoji(text);
    const cursorBar = {
      position: "absolute" as const,
      width: "0.08em",
      height: "0.88em",
      background: "currentColor",
      borderRadius: "0.01em",
      pointerEvents: "none" as const,
    };
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.opacity,
            maxWidth: "85%",
            whiteSpace: "pre-wrap",
            position: "relative",
          }}
        >
          {chars.map((ch, i) => {
            const isTyped = i < result.visibleChars;
            const isLastTyped = i === result.visibleChars - 1;
            const anchorCursor = isLastTyped && result.cursor;
            const charExit = result.charExits?.[i];
            const baseOpacity = isTyped ? 1 : 0;
            const finalOpacity = baseOpacity * (charExit?.opacity ?? 1);
            // During exit the per-char span needs inline-block so translateX
            // takes effect; whiteSpace: pre keeps space chars from collapsing.
            const exitStyle = charExit
              ? {
                  display: "inline-block" as const,
                  transform: `translateX(${charExit.translateX}px)`,
                  whiteSpace: "pre" as const,
                }
              : null;
            // Emoji handling: a cluster-start unit renders the mapped PNG; the
            // cluster's continuation units render nothing (image spans them).
            const emojiChar = emojiPlan?.starts.get(i);
            if (emojiPlan?.covered.has(i)) return null;
            return (
              <span
                key={i}
                style={{
                  opacity: finalOpacity,
                  position: anchorCursor ? "relative" : "static",
                  ...(exitStyle ?? {}),
                }}
              >
                {emojiChar ? <Emoji char={emojiChar} size={fontSize} /> : ch}
                {anchorCursor && (
                  <span
                    aria-hidden
                    style={{
                      ...cursorBar,
                      left: "100%",
                      top: "0.08em",
                      marginLeft: "0.12em",
                    }}
                  />
                )}
              </span>
            );
          })}
          {result.visibleChars === 0 && result.cursor && (
            <span
              aria-hidden
              style={{
                ...cursorBar,
                left: 0,
                top: "0.08em",
              }}
            />
          )}
        </div>
      </div>
    );
  }

  if (result.kind === "words") {
    // Render words inline-block with REAL space chars between them — word
    // spacing inherits from the container's typography defaults, matching
    // every other archetype's wrap behavior.
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.blockOpacity,
            transform: `${result.blockTransform} `,
            maxWidth: "85%",
          }}
        >
          {result.words.map((w, i) => (
            <span key={i}>
              <span
                style={{
                  display: "inline-block",
                  opacity: w.style.opacity,
                  transform: w.style.transform,
                }}
              >
                {renderWithEmoji(w.text, fontSize)}
              </span>
              {i < result.words.length - 1 ? " " : ""}
            </span>
          ))}
        </div>
      </div>
    );
  }

  if (result.kind === "hero") {
    // Per-word sizing: each active word fills its own moment optimally.
    const perWordFontSize = computeHeroFontSize(
      result.word.length,
      position,
      width,
      height,
      safeZone,
    );
    // Fixed-height slot so words of different sizes don't jump vertically.
    // Slot is the max possible hero size for this position; lineHeight: 1 on
    // the inner word locks the glyph box to the font height so flex-center
    // lands the glyph at the same Y for every word.
    const slotHeight =
      position === "center" ? 480 * scale : Math.min(220 * scale, height * 0.28 * 0.8);
    return (
      <div style={{ ...containerStyle, fontSize: perWordFontSize }}>
        <div
          style={{
            height: slotHeight,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              opacity: result.opacity,
              transform: `${result.transform} `,
              lineHeight: 1,
              ...(result.letterSpacing ? { letterSpacing: result.letterSpacing } : {}),
            }}
          >
            {renderWithEmoji(result.word, perWordFontSize)}
          </div>
        </div>
      </div>
    );
  }

  return null;
};

/**
 * Emoji — render emojis as inline PNG data-URI <img> elements.
 *
 * Why images, not the system emoji font: VanillaSky renders the same scene
 * three ways — real-DOM preview, client SVG-as-image export, server Puppeteer.
 * Raw-unicode emojis fall through to whatever emoji font the OS has (Mac=Apple,
 * Linux=Noto), so preview and export disagree. Inlining each emoji as a
 * data-URI <img> renders the SAME PNG in all three. Critically, the
 * client export rasterizes the frame via <img src="data:image/svg+xml">, which
 * can ONLY load inlined data-URI images (not @font-face, not external URLs) —
 * so data URIs are exactly what works there.
 *
 * Source artwork: emoji-datasource-google (Google Noto emoji set, Apache-2.0).
 * The map ships inside the publicly redistributed skill tarball, and Apple's
 * artwork is not licensed for redistribution — Noto's Apache-2.0 is. The set
 * is swappable via the generator's EMOJI_SET constant
 * (scripts/generate-emoji-map.mjs).
 *
 * Bundle: the generated char→dataURI map is ~1.1MB of base64, so it is
 * LAZY-LOADED via dynamic import and never enters the initial app bundle. The
 * import is kicked off eagerly at module load (below) — long before any export
 * or screenshot — so by the time a frame is captured the map has resolved.
 * Until it resolves, <Emoji> renders the raw unicode char, then re-renders to
 * the image when the map lands. Any emoji not in the map also falls back to the
 * raw char, so nothing ever breaks for custom/unmapped emojis.
 */

import * as React from "react";

let EMOJI_MAP: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;
const subscribers = new Set<() => void>();

function loadEmojiMap(): Promise<Record<string, string>> {
  if (loadPromise) return loadPromise;
  loadPromise = import("./emoji-map.generated")
    .then((mod) => {
      EMOJI_MAP = mod.default;
      subscribers.forEach((fn) => fn());
      return EMOJI_MAP;
    })
    .catch((err) => {
      // Network/chunk failure: leave map null → everything falls back to char.
      console.warn("[emoji] failed to load emoji map:", err);
      EMOJI_MAP = {};
      return EMOJI_MAP;
    });
  return loadPromise;
}

// Kick off the load immediately when this module is first imported (app/registry
// init), so the map is ready well before any export or server screenshot.
loadEmojiMap();

/**
 * Resolve once the emoji-PNG map has loaded (or definitively failed). Render
 * paths that capture frames MUST await this before their first capture so they
 * never screenshot a frame while emoji are still raw-unicode chars:
 *   - server: Render.tsx awaits before setting window.__ready
 *   - client export: export-video.ts awaits in the media-preload step
 * The preview path doesn't capture, so it can stay lazy (subscribers re-render
 * char → image when the map lands). On chunk failure this resolves to {} so
 * the await never hangs — everything falls back to the raw char.
 */
export function ensureEmojiMap(): Promise<Record<string, string>> {
  return loadEmojiMap();
}

/**
 * Returns the emoji-PNG data URI for an emoji char, or null if the map hasn't
 * loaded yet or the char isn't in the set (caller should fall back to the char).
 */
export function emojiToDataUri(char: string): string | null {
  if (!EMOJI_MAP) return null;
  const key = (char || "").trim();
  if (EMOJI_MAP[key]) return EMOJI_MAP[key];
  // Tolerate a trailing variation selector mismatch (U+FE0F).
  const stripped = key.replace(/️/g, "");
  if (stripped !== key && EMOJI_MAP[stripped]) return EMOJI_MAP[stripped];
  return null;
}

/** Subscribe to map-loaded so a component re-renders char → image when ready. */
function useEmojiMapReady(): boolean {
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    if (EMOJI_MAP) return;
    const fn = () => force();
    subscribers.add(fn);
    loadEmojiMap();
    return () => {
      subscribers.delete(fn);
    };
  }, []);
  return EMOJI_MAP != null;
}

export interface EmojiProps {
  /** The emoji character(s), e.g. "🎉". */
  char: string;
  /** Box size in px — matches the prior glyph's font-size so layout is identical. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the <img> (or fallback <span>). */
  style?: React.CSSProperties;
}

/**
 * Renders an emoji as an inline emoji-PNG <img> when available, else the raw
 * unicode char in a same-size box (so scale/opacity/transform are unchanged).
 */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  useEmojiMapReady();
  const uri = emojiToDataUri(char);

  if (!uri) {
    // Fallback: raw char sized to the same box so layout/scale are preserved.
    return (
      <span
        style={{
          fontSize: size,
          lineHeight: 1,
          display: "inline-block",
          ...style,
        }}
      >
        {char}
      </span>
    );
  }

  return (
    <img
      src={uri}
      alt={char}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    />
  );
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + color-emoji
 * runs, rendering each color emoji as an inline emoji-PNG <img> (via <Emoji>)
 * while leaving everything else as plain text.
 *
 * Why this exists: raw-unicode emoji fall through to the OS emoji font (Mac =
 * Apple, Linux = Noto), so the three render paths (preview / client SVG export
 * / server Puppeteer) disagree. Wrapping every template/AI-supplied string here
 * makes ALL color emoji render as the same mapped PNG in all three.
 *
 * What it does NOT touch: monochrome symbols (★ ✦ ✓ → ↑ …). Those render
 * identically as text across OSes, and imaging them would be wrong. The gate
 * is `emojiToDataUri()` — only clusters that resolve to a PNG in the
 * map become <img>; anything else (monochrome symbols, unmapped/custom
 * emoji, skin-tone variants not in the set) stays raw text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own <img> in sequence.
 *
 * Sizing: each emoji <img> is sized to `fontSizePx` (the surrounding font
 * size) so the emoji box matches a glyph box — width/line-count stay
 * ~identical to the raw-text layout, which keeps fitTextSize / archetype
 * char-count measurement valid (all string-based, never DOM-measured).
 */

import * as React from "react";
import { Emoji, emojiToDataUri } from "./index";

// Coarse "is this cluster a color-emoji candidate?" test. Deliberately broad:
// the real decision is whether emojiToDataUri() resolves it to a mapped PNG.
// This regex only needs to (a) catch the OS-divergent color ranges and (b)
// avoid flagging plain text/whitespace so we don't merge text into emoji runs.
//
//  - \u{1F000}-\u{1FAFF}  — main emoji planes (most pictographs)
//  - \u{2600}-\u{27BF}    — misc symbols + dingbats (color when + FE0F)
//  - \u{2B00}-\u{2BFF}    — stars/arrows block (⭐ lives here)
//  - \u{1F1E6}-\u{1F1FF}  — regional indicators (flags)
//  - \u{1F3FB}-\u{1F3FF}  — skin-tone modifiers
//  - \u{FE0F} | \u{200D} | \u{20E3} — VS16 / ZWJ / keycap combiners
//
// Combining/joiner codepoints (FE0F, ZWJ, keycap) are matched via alternation
// rather than inside the character class — eslint's
// no-misleading-character-class flags combining chars inside `[...]`, and
// alternation is equivalent here (we only test, never capture).
const EMOJI_CANDIDATE =
  /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u{FE0F}|\u{200D}|\u{20E3}/u;

function isEmojiCandidate(cluster: string): boolean {
  return EMOJI_CANDIDATE.test(cluster);
}

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters; emojiToDataUri's FE0F tolerance + the raw
  // fallback keep them from breaking. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji <img>. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> images for every mapped color emoji. Returns a single-element
 * `[text]` fast-path when there are no color emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!EMOJI_CANDIDATE.test(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    const uri = isEmojiCandidate(cluster) ? emojiToDataUri(cluster) : null;
    if (uri) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to its emoji-PNG
 * data URI and marks the cluster's CONTINUATION indices as covered (render
 * nothing for them — the start index's <img> already spans the whole cluster).
 *
 * Returns null when the text contains no mapped color emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !EMOJI_CANDIDATE.test(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isEmojiCandidate(cluster) && emojiToDataUri(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> for a correct map lookup.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render, color emoji replaced with emoji-PNG <img>. */
  children: string;
  /** Surrounding font size in px — sizes each emoji image to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji <img> runs. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares what variables it needs (auto-shown as input fields in the Studio)
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { ResolvedTokens } from "./tokens";
import type { GlobalStyle, VariableField, SafeZone } from "../video-config";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: GlobalStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * Brand tokens already resolved from `style`. Built-in templates import
   * resolveTokens directly; an ejected `custom_*` scene can't import anything,
   * so without this it has no way to reach the same values and ends up
   * hardcoding white, black and shadows — the body then looks generic next to
   * a frame that IS using the brand.
   */
  tokens?: ResolvedTokens;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}

/**
 * What a template can DO inside a video. A template can serve more than
 * one job — `bigNumber` is `["claim", "proof"]`; `media` is
 * `["atmosphere", "setup"]`. Used by the chat composer to pick templates
 * by scene-job rather than by the (less useful) category bucket.
 *
 * - `setup` — opens the world, names the subject, frames the question
 * - `claim` — makes a falsifiable statement the rest of the video earns
 * - `proof` — backs a claim with a number, quote, mockup, code, or chart
 * - `atmosphere` — breathing room; ties scenes together visually
 * - `payoff` — punchline, reveal, or satisfying answer to an earlier setup
 * - `punctuation` — short energy beat that breaks pattern or lands a joke
 * - `ask` — pushes the viewer to the next action; closer-territory only
 */
export type TemplateJob = "setup" | "claim" | "proof" | "atmosphere" | "payoff" | "punctuation" | "ask";

/**
 * The visual register a template lives in — what the *viewer* notices
 * before reading any copy. The chat's diversity rule reads this rather
 * than `category` because two `card-led` bodies look the same to the
 * viewer even when they're a `testimonial` and a `bigNumber`.
 *
 * - `motion-led` — animation IS the content (confetti, emoji rain, charts)
 * - `typography-led` — text fills the frame (bigNumber, ctaLogo, tripleStats)
 * - `device-led` — phone/browser/terminal frame is the focal element
 * - `card-led` — quote/feature/comparison cards
 * - `mockup-led` — full UI surface (chat thread, search results, app feed)
 */
export type TemplateRegister =
  | "motion-led"
  | "typography-led"
  | "device-led"
  | "card-led"
  | "mockup-led";

/**
 * A registered scene template.
 */
export interface SceneTemplate {
  id: string;
  /** Built-in templates leave these blank — DB owns them. Vibecoded
   *  templates carry their own here since they have no DB row. */
  label?: string;
  description?: string;
  category?: string | null;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  /** Thumbnail URL for visual picker (optional) */
  thumbnail?: string;
  /** If true, template consumes the video-level defaultTextArchetype */
  usesGlobalTextEffect: boolean;
  /** If true, template uses the video-level defaultTransition */
  usesGlobalTransition: boolean;
  /** If true, template uses the video-level defaultBackgroundEffect */
  usesGlobalBackgroundEffect: boolean;
  /**
   * Spatial budget for text effects.
   * - "tight" (default): text shares the frame with UI (mockup, chart). Expressive
   *   effects are auto-clamped to contained equivalents to prevent clipping.
   * - "open": text is the focal element (bg-* templates). All effects allowed.
   */
  textCanvas?: "tight" | "open";
  /**
   * Hard input gates — what this template needs from the user's input to fire
   * legitimately. The AI uses these to filter out templates that would force
   * it to invent content (e.g. \`bigNumber\` without a real number).
   *
   * Set to true when the template's value depends on input that the model
   * can't fabricate honestly: a stat, a quote, an uploaded screenshot.
   * Defaults to false (no constraint).
   */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  /** Template can be backed by Pexels stock footage (e.g. \`media\`). */
  allowsStockMedia?: boolean;
  /** Variable schema — Studio auto-generates inputs from this */
  variableSchema: Record<string, VariableField>;
  /** Default values for all variables */
  defaultVariables: Record<string, unknown>;
  /** Minimum scene duration in seconds */
  minDuration?: number;
  /** Recommended scene duration in seconds */
  preferredDuration?: number;
  /** The React component that renders this template */
  component: React.FC<SceneTemplateProps>;
}

/**
 * Serializable template metadata (no component) — for edge functions, API, MCP.
 */
export interface SceneTemplateMetadata {
  id: string;
  usesGlobalTextEffect: boolean;
  usesGlobalTransition: boolean;
  usesGlobalBackgroundEffect: boolean;
  textCanvas?: "tight" | "open";
  /** Hard input gates — see SceneTemplate.requiresStat etc. */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  allowsStockMedia?: boolean;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  variableSchema: Record<string, VariableField>;
  defaultVariables: Record<string, unknown>;
  minDuration?: number;
  preferredDuration?: number;
}

/**
 * VideoConfig — React template-based architecture.
 *
 * Every scene is a React template. Templates declare their variables via a schema,
 * and the Studio auto-generates input UI from it. AI picks templates by matching
 * descriptions to the user's prompt.
 */

// ─── Orientation & Dimensions ──────────────────────────────────

export type Orientation = "portrait" | "landscape";

export interface VideoDimensions {
  width: number;
  height: number;
  aspectRatio: string;
}

export interface SafeZone {
  top: number;
  bottom: number;
  left: number;
  right: number;
}

export function getDimensions(orientation: Orientation = "portrait"): VideoDimensions {
  return orientation === "landscape"
    ? { width: 1920, height: 1080, aspectRatio: "16 / 9" }
    : { width: 1080, height: 1920, aspectRatio: "9 / 16" };
}

export function getSafeZone(orientation: Orientation = "portrait"): SafeZone {
  return orientation === "landscape"
    ? { top: 108, bottom: 108, left: 192, right: 192 }    // SMPTE broadcast safe (10%)
    : { top: 100, bottom: 100, left: 60, right: 60 };     // Balanced safe zone — enough margin without eating content
}

/**
 * Scale a safe zone's insets — the density dial's second lever.
 *
 * Every template receives `safeZone` and lays text out against it, so
 * widening it is the one way to add whitespace across all of them without
 * touching a template. Rounded to whole pixels so preview and the SVG export
 * path agree; a factor of 1 returns the insets unchanged.
 */
export function scaleSafeZone(zone: SafeZone, factor: number): SafeZone {
  if (factor === 1) return zone;
  return {
    top: Math.round(zone.top * factor),
    bottom: Math.round(zone.bottom * factor),
    left: Math.round(zone.left * factor),
    right: Math.round(zone.right * factor),
  };
}

// ─── Core Config ───────────────────────────────────────────────

export interface VideoConfig {
  orientation?: Orientation;
  audio?: AudioConfig;
  scenes: SceneConfig[];
  style: GlobalStyle;
  meta?: VideoMeta;
}

// ─── Audio ─────────────────────────────────────────────────────

export interface AudioConfig {
  trackId: string;
  audioUrl: string;
  duration: number;
  beatDetection: BeatDetectionConfig;
  beatMarkers: BeatMarker[];
  /** Volume 0.0-1.0. Default 1.0 (full track volume). */
  volume?: number;
  /** Fade-out duration in milliseconds at end of audio. When unset, falls
   *  back to min(lastSceneDuration, 3s) via `defaultFadeOutMs()` — the fade
   *  ramps down over the closer instead of cutting hard. Set explicitly
   *  (including 0) to override. */
  fadeOutMs?: number;
}

export interface BeatDetectionConfig {
  sensitivity: number;
  targetBeats?: number;
  minInterval?: number;
}

export interface BeatMarker {
  time: number;
  manual?: boolean;
  energy?: "high" | "medium" | "low";
}

// ─── Scene ─────────────────────────────────────────────────────

export interface SceneConfig {
  id: string;
  templateId: string;
  variables: Record<string, unknown>;
  /** Text archetype for this scene. One of the 6 names in TEXT_ARCHETYPES. */
  textArchetype?: string;
  // Note: scene-level transition override (formerly `transition?: string` with
  // a UI selector for crossfade / cut / slide / flash / dip / zoom) was
  // removed when none of the eight options were wired to the renderer.
  // Renderer now picks cut vs dissolve from `shouldDissolveBetween` in
  // scene-resolver.ts. Re-introduce as `transition: "cut" | "dissolve"` here
  // if real exceptions to the continuity rule appear.
  /** Override video-level default background effect (for templates that opt in) */
  backgroundEffect?: string;
  /**
   * Per-scene background override. When set, this scene renders on the
   * overridden gradient (accent + secondary) instead of the video-level
   * brand. Solid mode = accent equals secondary; gradient = distinct.
   */
  backgroundOverride?: { accent: string; secondary: string };
  timing: TimingConfig;
  /** AI-generated alternative templates with purpose-written copy. 0–3 per scene. */
  alternatives?: AlternativeTemplate[];
  /**
   * Raw React source for vibecoded (custom_*) templates. Set on save so
   * server-side render (`/render` + Trigger.dev export) can rehydrate the
   * template without the client's sessionStorage. Empty for built-in
   * templates. Stripped before display — never read at runtime in the Studio
   * (the in-memory `customTemplates` registry is the source of truth there).
   */
  componentSource?: string;
  /**
   * Where an ejected scene came from. Without it a `custom_*` scene is an
   * anonymous blob: nothing records which registry item it started as or
   * which version, so when the upstream item changes — a safe-zone fix, an
   * export constraint, a bug — there is no way to tell the owner their copy
   * is behind, and no way to show them what changed.
   *
   * Set on eject. `vanillasky diff` compares `originHash` against the current
   * registry item; a mismatch means upstream moved since you ejected.
   */
  origin?: SceneOrigin;
}

/** Provenance for an ejected (`custom_*`) scene. */
export interface SceneOrigin {
  /** Registry item this was ejected from, e.g. "bigNumber" or "countUpNumber". */
  item: string;
  /** Registry version at eject time. */
  version?: string;
  /** Hash of the upstream source at eject time — the thing diff compares. */
  sourceHash?: string;
  /** ISO date, for "you ejected this 6 months ago" context. */
  ejectedAt?: string;
}

// ─── Alternative Template ─────────────────────────────────────

export interface AlternativeTemplate {
  templateId: string;
  variables: Record<string, unknown>;
  /** Human-readable rationale shown in the picker (e.g. "More cinematic", "Social proof angle") */
  rationale?: string;
}

// ─── Variable Schema ──────────────────────────────────────────

export interface VariableField {
  type: "string" | "number" | "boolean" | "enum" | "media" | "color" | "data-points";
  label: string;
  default?: unknown;
  /** Options for enum type */
  options?: string[];
  required?: boolean;
  /** Help text shown in Studio and used by AI for context */
  description?: string;
}

// ─── Timing ────────────────────────────────────────────────────

export interface TimingConfig {
  beatStart?: number;           // beat marker index (beat-sync mode)
  beatEnd?: number;             // beat marker index (beat-sync mode)
  startTime?: number;           // seconds (time-based mode)
  endTime?: number;             // seconds (time-based mode)
  fixedDuration?: number;       // seconds (no-audio mode)
  durationWeight?: number;      // relative weight for auto-distribution
}

// ─── Style ─────────────────────────────────────────────────────

export interface GlobalStyle {
  font: string;
  brandKit?: BrandKit;
  /**
   * Named style preset — the frame-level look (background family, title type
   * treatment, title placement). One token that moves several decisions
   * coherently, so two videos with the same brand colors don't come out
   * looking identical. Resolved in scene-templates/tokens.ts; unset or
   * unknown falls back to the default preset, which reproduces the original
   * look exactly. See STYLE_PRESETS for the list.
   */
  preset?: string;
  /**
   * How much room the frame gives its content — `airy` | `normal` |
   * `packed`. Orthogonal to `preset`: the preset picks the look, this picks
   * how full the frame reads. Scales headline type size and the safe-zone
   * insets every template lays out against. Unset or unknown = `normal`,
   * which is a no-op. See DENSITY_SCALES in scene-templates/tokens.ts.
   */
  density?: string;
  /**
   * How hard the motion hits — `calm` | `normal` | `punchy`. Scales every
   * text-archetype entrance and exit phase. Unset or unknown = `normal`,
   * which is a no-op. See MOTION_SCALES in scene-templates/tokens.ts.
   */
  motion?: string;
  /** Default text archetype when a scene doesn't set one. */
  defaultTextArchetype?: string;
  /** Default transition between scenes */
  defaultTransition?: string;
  /** Default background effect — consumed by templates with usesGlobalBackgroundEffect: true */
  defaultBackgroundEffect?: string;
}

// ─── Brand Kit ────────────────────────────────────────────────

export interface BrandKit {
  /** Primary brand color — drives one half of the gradient mesh and most accents. */
  accent: string;
  /** Secondary brand color — drives the other half of the gradient mesh.
   *  When equal to accent, the gradient collapses to a flat color (solid mode). */
  secondary?: string;
  /** Optional explicit text color override — defaults to white (#ffffff) when
   *  not set. Templates render scrims/vignettes to handle bright surfaces. */
  text?: string;
  logoDataUrl?: string;
  /**
   * Solid scene background override. When set, the gradient renderer
   * collapses to this single color — use it when the brand has a clear dark
   * surface (e.g., dark body text on a light marketing page reads as a real
   * navy / charcoal brand color). Pairing it with `accent` in a gradient
   * produces muddy results, so anchor the bg flat and let `accent` handle
   * highlights.
   */
  bg?: string;
  /**
   * Normalized URL the brand kit was derived from, when it came from a URL
   * rather than being set explicitly. Acts as a cache key: a later config
   * pointing at the same URL can reuse the kit instead of re-deriving it.
   */
  sourceUrl?: string;

  // ─── Extended fields for primitive composition ────────────────────
  /** Deepest background surface — defaults to a near-black if unset. */
  surface?: string;
  /** Elevated card / panel surface — defaults to surface + 4% lighten. */
  surface_elevated?: string;
  /** Muted text color for labels, footers, supporting copy. Default #a7a6b0. */
  muted?: string;
  /** Script accent font family for handwritten callouts (Caveat-style). Default "Caveat". */
  script_font?: string;
  /** Inferred mood/vibe from URL capture — used downstream for music selection. */
  vibe?: "default" | "reflective" | "edgy" | "playful" | "premium";
}

// ─── Gradient / Background Style (used by VideoManager, VideoCardPreview, BackgroundShowcase for saved videos) ──

export type BackgroundStyle = "solid" | "blobs" | "waves" | "blurry-gradient" | "circles" | "blob-scene" | "layered-waves" | "stacked-waves" | "blob-scatter" | "polygon-scatter" | "symbol-scatter" | "radial-gradient" | "mesh-gradient" | (string & {});

export interface PatternParams {
  complexity?: number;
  contrast?: number;
  size?: number;
  count?: number;
  balance?: number;
  variant?: "solid" | "outline";
  direction?: "up" | "down" | "left" | "right";
}

export interface GradientConfig {
  colors: [string, string];
  style: BackgroundStyle;
  animationSpeed: number;
  params?: PatternParams;
}

// ─── Meta ──────────────────────────────────────────────────────

export interface VideoMeta {
  name?: string;
  prompt?: string;
  sourceUrl?: string;
  createdAt?: string;
  mood?: string[];
  videoType?: string;
  /** Video format — the four shipped formats. See `src/lib/format-definitions.ts`
   *  for each one's slot contract; the CLI validator enforces the differences. */
  format?: "launch" | "review" | "milestone" | "update";
  trackRationale?: string;
  templateRationale?: string;
  source?: string;
  uploadedMediaUrls?: string[];
  /** Flat list of images the user uploaded on the landing page. The chat
   *  routes them to scenes via vision + setSceneMedia on turn 0. */
  uploadedImages?: string[];
  documentContent?: string;
  /** Stable identifier for the studio chat thread tied to this config.
   *  Lazily assigned the first time the user opens the chat, persisted via
   *  the same localStorage path as the rest of the config so the chat
   *  history (kept in sessionStorage under this key) can be rehydrated
   *  across tab switches and page reloads within a session. */
  chatId?: string;
  /** The `shared_configs` row this video is persisted to. Stamped when a
   *  config loads from `?config=<id>` and on the first autosave/export of a
   *  new build. Anchors continuous autosave + export to a single row
   *  (update-in-place) instead of minting a new row per save. */
  savedConfigId?: string;
  /** Stamped server-side by save-config when markExported is passed. */
  exported_at?: string;
}

/**
 * The declared format, from either place it can live.
 *
 * The CLI and the skill write `"format": "launch"` at the top level (that's
 * what `vanillasky validate` reads), while the web app stores it under
 * `meta.format`. A config written by an agent therefore looks format-less to
 * the app — which quietly changed how the music picker filtered. Read both
 * until the two conventions are reconciled.
 */
export function resolveFormat(config: VideoConfig): VideoMeta["format"] | undefined {
  const top = (config as VideoConfig & { format?: VideoMeta["format"] }).format;
  return config.meta?.format ?? top;
}

// ─── Validation ────────────────────────────────────────────────

export function validateVideoConfig(config: unknown): config is VideoConfig {
  if (!config || typeof config !== "object") return false;
  const c = config as Record<string, unknown>;

  if (!Array.isArray(c.scenes) || c.scenes.length === 0) return false;
  if (!c.style || typeof c.style !== "object") return false;

  const style = c.style as Record<string, unknown>;
  if (typeof style.font !== "string") return false;

  for (const scene of c.scenes as Record<string, unknown>[]) {
    if (!scene.id || typeof scene.id !== "string") return false;
    if (!scene.templateId || typeof scene.templateId !== "string") return false;
    if (!scene.timing || typeof scene.timing !== "object") return false;
  }

  // Validate audio if present
  if (c.audio) {
    const audio = c.audio as Record<string, unknown>;
    if (typeof audio.trackId !== "string") return false;
    if (typeof audio.audioUrl !== "string") return false;
    if (typeof audio.duration !== "number") return false;
    if (!Array.isArray(audio.beatMarkers)) return false;
    if (!audio.beatDetection || typeof audio.beatDetection !== "object") return false;
  }

  return true;
}

// ─── Factory ───────────────────────────────────────────────────

export function createDefaultScene(overrides?: Partial<SceneConfig>): SceneConfig {
  return {
    id: crypto.randomUUID(),
    templateId: "media",
    variables: {
      texts: "",
      mediaUrl: "",
      mediaKeyword: "",
    },
    timing: { fixedDuration: 3 },
    ...overrides,
  };
}
